// U14 (EMA-16) alert-to-linear, step 1: one item per CRITICAL alert in the Alertmanager webhook payload, each
// carrying the GraphQL lookup for its open/recent Linear incident. The Linear ids live here, and only here.
const CONFIG = {
  teamId: 'd78368d2-c0d8-4c52-a6eb-46d4fb3e89bb',     // team EMA
  projectId: '1b6e8535-4d91-4846-8da8-df7b21dba721',  // project Weyland Lab
  labelId: '701dccc2-deca-4955-8664-73f636197d2c',    // label `incident`
  todoStateId: 'c7a62aa5-03d2-4248-836d-d572370b3c0b',
  doneStateId: '7bab9b38-14d0-438f-8970-ed05185a81f9',
  // A re-fire within this window of the incident closing REOPENS it (flapping) instead of opening a new one.
  reopenWindowHours: 24,
};

const body = $input.first().json.body || {};
if (!Array.isArray(body.alerts)) {
  // Not an Alertmanager payload. Failing makes the webhook answer 500, so a misrouted sender sees it.
  throw new TypeError('payload has no alerts[] - not an Alertmanager webhook');
}

const FIND = `query($marker: String!, $team: ID!, $label: ID!) {
  issues(first: 10, filter: {
    team: { id: { eq: $team } }, labels: { some: { id: { eq: $label } } },
    description: { contains: $marker }, state: { type: { nin: ["canceled", "duplicate"] } }
  }) { nodes { id identifier url createdAt completedAt state { type } } }
}`;

return body.alerts
  .filter((a) => a.labels?.severity === 'critical' && a.fingerprint)
  .map((a) => {
    const marker = `alert-fingerprint: ${a.fingerprint}`;
    return {
      json: {
        config: CONFIG,
        externalURL: body.externalURL || '',
        alert: {
          fingerprint: a.fingerprint,
          status: a.status,
          labels: a.labels || {},
          annotations: a.annotations || {},
          startsAt: a.startsAt,
          endsAt: a.endsAt,
          generatorURL: a.generatorURL || '',
          marker,
        },
        request: { query: FIND, variables: { marker, team: CONFIG.teamId, label: CONFIG.labelId } },
      },
    };
  });

// U14 step 2: pair each lookup with its alert and decide ONE action. Emits only the alerts that need a Linear write.
//   firing,   open incident                      -> nothing (Alertmanager re-sends every repeat_interval; no spam)
//   firing,   incident closed < reopen window    -> reopen + comment (flapping keeps ONE issue)
//   firing,   none, or closed longer ago         -> create
//   resolved, open incident                      -> comment + close
//   resolved, none open                          -> nothing (resolved notifications are re-sent too)
const alerts = $('Critical alerts').all();
const lookups = $input.all();
if (lookups.length !== alerts.length) {
  throw new Error(`lookup count ${lookups.length} != alert count ${alerts.length}`);
}

const UPDATE = `mutation($id: String!, $state: String!, $body: String!) {
  issueUpdate(id: $id, input: { stateId: $state }) { success }
  commentCreate(input: { issueId: $id, body: $body }) { success }
}`;
const CREATE = `mutation($input: IssueCreateInput!) {
  issueCreate(input: $input) { success issue { identifier url } }
}`;

const md = (s) => String(s ?? '').replaceAll('|', String.raw`\|`).replaceAll('\n', ' ');

function describe(alert, externalURL) {
  const l = alert.labels;
  const a = alert.annotations;
  const rows = Object.keys(l).sort((x, y) => x.localeCompare(y)).map((k) => `| ${md(k)} | ${md(l[k])} |`).join('\n');
  const links = [
    a.runbook_url && `- Runbook: ${a.runbook_url}`,
    alert.generatorURL && `- Prometheus query: ${alert.generatorURL}`,
    externalURL && `- Alertmanager: ${externalURL}`,
  ].filter(Boolean).join('\n');
  return [
    `**${a.summary || l.alertname}**`,
    a.description || '',
    `Started: ${alert.startsAt}`,
    `| Label | Value |\n| --- | --- |\n${rows}`,
    links,
    'Opened by the n8n workflow `alert-to-linear` (U14). Telegram paged separately. This issue closes itself when '
      + 'the alert resolves, and reopens if it fires again within 24 h.',
    alert.marker,
  ].filter(Boolean).join('\n\n');
}

function createRequest(alert, config, externalURL) {
  const ns = alert.labels.namespace ? ` (${alert.labels.namespace})` : '';
  return { query: CREATE, variables: { input: {
    teamId: config.teamId, projectId: config.projectId, labelIds: [config.labelId],
    stateId: config.todoStateId, priority: 1,
    title: `U14 incident — ${alert.labels.alertname}${ns}`, description: describe(alert, externalURL),
  } } };
}

// The table at the top of this file, as code. Returns { action, request } or null for "nothing to write".
function decide(alert, newest, config, externalURL) {
  const open = Boolean(newest) && newest.state.type !== 'completed';
  if (alert.status === 'resolved') {
    if (!open) return null;
    return { action: 'close', request: { query: UPDATE, variables: { id: newest.id, state: config.doneStateId,
      body: `Resolved at ${alert.endsAt} — closed by alert-to-linear.` } } };
  }
  if (alert.status !== 'firing' || open) return null;
  const closedAgoH = newest?.completedAt ? (Date.now() - Date.parse(newest.completedAt)) / 36e5 : Infinity;
  if (closedAgoH < config.reopenWindowHours) {
    return { action: 'reopen', request: { query: UPDATE, variables: { id: newest.id, state: config.todoStateId,
      body: `Fired again at ${alert.startsAt} — reopened (it resolved ${closedAgoH.toFixed(1)} h ago).` } } };
  }
  return { action: 'create', request: createRequest(alert, config, externalURL) };
}

function newestIssue(res) {
  if (res.errors) throw new Error(`Linear lookup failed: ${JSON.stringify(res.errors).slice(0, 300)}`);
  const nodes = res.data?.issues?.nodes;
  if (!Array.isArray(nodes)) throw new TypeError('Linear lookup returned no issues[] - refusing to guess');
  return [...nodes].sort((x, y) => y.createdAt.localeCompare(x.createdAt))[0];
}

const out = [];
lookups.forEach((lookup, i) => {
  const { alert, config, externalURL } = alerts[i].json;
  const newest = newestIssue(lookup.json);
  const decision = decide(alert, newest, config, externalURL);
  if (decision) out.push({ json: { ...decision, alertname: alert.labels.alertname, fingerprint: alert.fingerprint,
    issue: newest?.identifier || null } });
});
return out;

// U14 step 3: every Linear write must report success. Linear answers GraphQL errors with HTTP 200, so the HTTP
// node alone would call a refused write a success. Throwing here makes the webhook answer 500, Alertmanager retries
// and counts the failure (alertmanager_notifications_failed_total{integration="webhook"}).
const actions = $('Decide').all();
const results = $input.all();
const done = results.map((r, i) => {
  const res = r.json;
  const what = actions[i].json;
  if (res.errors) throw new Error(`Linear ${what.action} failed: ${JSON.stringify(res.errors).slice(0, 300)}`);
  const ops = Object.values(res.data || {});
  if (!ops.length || ops.some((op) => op?.success !== true)) {
    throw new Error(`Linear ${what.action} for ${what.alertname} did not report success`);
  }
  return `${what.action} ${res.data.issueCreate?.issue?.identifier || what.issue} (${what.alertname})`;
});
return [{ json: { applied: done.length, done } }];
